import networkx as nx

def get_component_sizes_after_removing_v(n, v_idx):
    subsets = []
    for i in range(1, 1 << n):
        s = set()
        for j in range(n):
            if (i >> j) & 1:
                s.add(j)
        subsets.append(s)

    num_subsets = len(subsets)
    G = nx.Graph()
    G.add_nodes_from(range(num_subsets))
    for i in range(num_subsets):
        for j in range(i + 1, num_subsets):
            if not (subsets[i] & subsets[j]):
                G.add_edge(i, j)

    # K1 is all subsets except the last one (the one with all 1s)
    # Actually, let's just remove the last one from the graph
    G.remove_node(num_subsets - 1)

    # Now remove v
    G.remove_node(v_idx)

    components = list(nx.connected_components(G))
    return [len(c) for c in components]

# We'll test for n=5 to see the pattern
for n in range(3, 6):
    print(f"n={n}:")
    found_v = False
    for v_idx in range(1, (1 << n) - 1):
