        if len(sizes) > 1:
            print(f"  v_idx {v_idx} gives sizes {sizes}")
            found_v = True
            break
    if not found_v:
        print("  No v found")

import networkx as nx

def find_large_components(n):
    subsets = []
    for i in range(1, 1 << n):
        s = set()
        for j in range(n):
            if (i >> j) & 1:
                s.add(j)
        subsets.append(s)

    num_subsets = len(subsets)
    G = nx.Graph()
    G.add_nodes_from(range(num_subsets))
    for i in range(num_subsets):
        for j in range(i + 1, num_subsets):
            if not (subsets[i] & subsets[j]):
                G.add_edge(i, j)

    G.remove_node(num_subsets - 1)

    for v in range(num_subsets - 1):
        G_minus_v = G.copy()
        G_minus_v.remove_node(v)
        components = list(nx.connected_components(G_minus_v))
        if len(components) > 1:
            comp_sizes = [len(c) for c in components]
            # Check if any two components could provide 2004 each (scaled for n=6)
            # For n=6, target is 20 (half of 40).
            target = 20 
            # Actually, we'll just print the component sizes.
            if any(s >= target for s in comp_sizes) and sum(comp_sizes) >= 2*target:
                # Check if there are two components that each have at least target
                # Wait, it could be that one component is large enough to be split.
                # But we need the two sets R and C to have no edges between them.
                # This means R and C must be in DIFFERENT components.
                # So we need at least two components with size >= target.
                count = 0
                for s in comp_sizes:
                    if s >= target:
                        count += 1
                if count >= 2:
                    return True, v, comp_sizes
    return False, None, None

