import networkx as nx

def find_max_two_components_correct(n, target):
    subsets = []
    for i in range(1, 1 << n):
        s = set()
        for j in range(n):
            if (i >> j) & 1:
                s.add(j)
        subsets.append(s)

    num_subsets = len(subsets)
    G = nx.Graph()
    G.add_nodes_from(range(num_subsets))
    for i in range(num_subsets):
        for j in range(i + 1, num_subsets):
            if not (subsets[i] & subsets[j]):
                G.add_edge(i, j)

    G.remove_node(num_subsets - 1)

    articulation_points = list(nx.articulation_points(G))
    for v in articulation_points:
        G_minus_v = G.copy()
        G_minus_v.remove_node(v)
        components = list(nx.connected_components(G_minus_v))
        comp_sizes = [len(c) for c in components]

        # Check if any subset of comp_sizes sums to target
        # Use dynamic programming for subset sum
        possible_sums = {0}
        for s in comp_sizes:
            new_sums = set()
            for p in possible_sums:
                if p + s <= target:
                    new_sums.add(p + s)
            possible_sums.update(new_sums)

        if target in possible_sums:
            # We also need to ensure the remaining sum is at least target
            total_sum = sum(comp_sizes)
            if total_sum - target >= target:
                return True, v, comp_sizes
    return False, None, 0

