def max_r_plus_c(n):
    subsets = []
    for i in range(1, 1 << n):
        s = set()
        for j in range(n):
            if (i >> j) & 1:
                s.add(j)
        subsets.append(s)

    num_subsets = len(subsets)
    adj = [[] for _ in range(num_subsets)]
    for i in range(num_subsets):
        for j in range(i + 1, num_subsets):
            if not (subsets[i] & subsets[j]):
                adj[i].append(j)
                adj[j].append(i)

    max_val = 0
    # We want to find R, C disjoint such that no edges between them.
    # This means R and C are unions of connected components of some subgraph.
    # The largest such R+C is achieved when the subgraph is the whole graph G
    # and we pick R and C to be unions of its components.
    # But wait, the question is about ANY R, C.
    # If we pick R, C to be unions of components of G, then R, C are cross-intersecting.
    # So max |R| + |C| is the sum of the sizes of all components of G, 
    # provided we have at least two components.
    # If G has only one component, then we need to remove some vertices to make it disconnected.
    # The max size is num_subsets - kappa(G).

    import networkx as nx
    G = nx.Graph()
    G.add_nodes_from(range(num_subsets))
    for i in range(num_subsets):
        for j in range(i + 1, num_subsets):
            if not (subsets[i] & subsets[j]):
                G.add_edge(i, j)

    if nx.is_connected(G):
        # If connected, max |R|+|C| = num_subsets - kappa(G)
        # We need to find the smallest k such that G-S is disconnected.
        # This is exactly the vertex connectivity.
        kappa = nx.node_connectivity(G)
        return num_subsets - kappa
    else:
        return num_subsets

